    public func eventStream(_ request: EventStreamRequest) async throws -> AsyncThrowingStream<GridEvent, Swift.Error> {
        let stream = try await host.openStream(
            service: "VolvoxGridService",
            method: "/volvoxgrid.v1.VolvoxGridService/EventStream"
        )
        try await stream.send(request.serializedData())
        try await stream.closeSend()
        return AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    while let data = try await stream.recv() {
                        let msg = try GridEvent(serializedBytes: data)
                        continuation.yield(msg)
                    }
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

